function s(n: number) : string {
    let r : string = ""

    for (let i : number = 1; i <= n; i++) {
        if (i < (n/2)) {
            r = (n % i) + r
        } else {
            r = r + (n % i)
        }
    }
    return r
}

function x(n : number) : number {
    let soma : number = 0

    for (let i : number = 0; i <= n; i++) {
        soma = (i ** 2) - (3 ** i ) + 5
    }

    return soma * i
}

